using System;using System.IO;using System.Text.Json;using Exoduser.UnityPort;using Exoduser.UnityPort.Core;
static class Program {
 static int checks,fail;static void Check(bool value,string name){checks++;if(!value){fail++;Console.WriteLine("FAIL "+name);}}
 static void Main(string[] args){
 Check(!NativeEnemyRigPolicy.Requested(null),"default sprite");Check(NativeEnemyRigPolicy.Requested(new[]{"--enemy-render=rigpixel"}),"opt in");Check(!NativeEnemyRigPolicy.Requested(new[]{"--enemy-render=rigpixel","--enemy-render=sprite"}),"last flag wins");Check(NativeEnemyRigPolicy.Requested(new[]{"--enemy-render","rigpixel"}),"split flag");
 var e=new EnemyState{Id=1,Etype=4,Alive=true,Radius=16,Web=new EnemySpawn{s="idle"}};var p=new NativeEnemyRigPolicy();
 Check(p.Sample(e,100,0).State==EnemyRigState.Idle,"idle");Check(p.Sample(e,101,2).State==EnemyRigState.Move,"move");
 e.Web.s="g2Tell";e.Web.MeleeTellMax=36;e.Web.MeleeTimer=36;e.Web.MeleeTellSerial=1;var s=p.Sample(e,102,2);Check(s.State==EnemyRigState.Tell&&s.Normalized==0,"tell first tick");e.Web.MeleeTimer=1;s=p.Sample(e,137,2);Check(Math.Abs(s.Normalized-35.0/36)<.0001,"tell exact Core progress");
 e.Web.s="g2Active";e.Web.MeleeActiveMax=3;e.Web.MeleeTimer=3;s=p.Sample(e,138,2);Check(s.State==EnemyRigState.Active&&s.Normalized==0,"active starts at Core frame");
 e.Web.MeleeTimer=1;Check(Math.Abs(p.Sample(e,140,2).Normalized-2.0/3)<.0001,"active last tick");e.Web.s="g2Gap";e.Web.MeleeTimer=22;Check(p.Sample(e,141,2).State==EnemyRigState.Recover,"combo gap");
 e.MeleeFreezeUntil=200;e.MeleeParriedTick=155;Check(p.Sample(e,155,2).State==EnemyRigState.Recover,"parried counter window");e.MeleeFreezeUntil=0;e.Stunned=180;Check(p.Sample(e,156,2).State==EnemyRigState.Stagger,"poise break");e.Stunned=0;e.Web.s="idle";e.HurtTicks=8;Check(p.Sample(e,157,2).State==EnemyRigState.Hit,"hurt");
 e.Alive=false;Check(p.Sample(e,158,2).State==EnemyRigState.Death,"death priority");Check(p.Sample(e,158,2).Age==0,"same tick cannot advance death");Check(p.Sample(e,200,2).Age==42,"death uses Core ticks");e.Alive=true;e.HurtTicks=0;Check(p.Sample(e,201,2).State!=EnemyRigState.Death,"revive clears death");
 var ranged=new EnemyState{Alive=true,Etype=1,Web=new EnemySpawn{s="idle",_projChargeT=60}};var q=new NativeEnemyRigPolicy();Check(q.Sample(ranged,1,0).State==EnemyRigState.Tell,"ranged charge");ranged.Web._projChargeT=1;Check(q.Sample(ranged,60,0).Normalized>0.98,"ranged last charge frame");ranged.Web._projChargeT=0;Check(q.Sample(ranged,61,0).State==EnemyRigState.Active,"ranged release");Check(q.Sample(ranged,64,0).State==EnemyRigState.Recover,"ranged recovery");
 for(int i=0;i<40;i++){double ratio=NativeEnemyRigPolicy.ImpactRatio(i%2==0?0:1,i==39);Check(ratio>=.6&&ratio<=(i==39?1.2:1),"impact scale range "+i);}
 Check(NativeEnemyRigPolicy.AnchorRatio(-1)==0,"anchor low clamp");Check(NativeEnemyRigPolicy.AnchorRatio(2)==1,"anchor high clamp");Check(NativeEnemyRigPolicy.AnchorRatio(double.NaN)==.55,"invalid anchor fallback");

 var catalog=JsonSerializer.Deserialize<EnemyRigCatalog>(File.ReadAllText(args[0]),new JsonSerializerOptions{IncludeFields=true});Check(catalog.models.Length==6,"five first-wave models plus distinct start eye mass");
 EnemyRigDefinition eye=null,spine=null;foreach(var d in catalog.models){if(d.etype==4&&d.startEyeMass)eye=d;if(d.etype==1)spine=d;Check(d.height>0&&d.baseRadius>0&&d.deathTicks>0,"positive model dimensions");Check(d.chestRatio>=0&&d.chestRatio<=1,"chest inside body");Check(File.Exists(Path.Combine(Path.GetDirectoryName(args[0]),"..",d.modelResource+".fbx")),"model asset exists");}
 var ordinary=new EnemyState{Etype=4,Alive=true};Check(!eye.Matches(ordinary),"ordinary carapace cannot select start eye mass");ordinary.IsStartEyeMass=true;Check(eye.Matches(ordinary),"fixed start eye mass key");ordinary.IsGhoul=true;Check(!eye.Matches(ordinary),"ghoul cannot borrow eye model");Check(spine.Matches(new EnemyState{Etype=1,Elite=3}),"same spine model for elites");Check(!spine.Matches(new EnemyState{Etype=1,IsBoss=true}),"boss stays separate");
 var sim=new Simulation(new SimulationConfig{StageIndex=0,StartX=2000,StartY=2000},47);sim.SpawnStartEnemies();int tags=0;foreach(var mob in sim.Enemies){if(mob.IsStartEyeMass){tags++;Check(mob.Etype==4,"only start eye masses tagged");}}Check(tags==2,"real StartMobs tags exactly two");var extra=sim.SpawnEnemy(2100,2100,4);Check(extra!=null&&!extra.IsStartEyeMass&&!eye.Matches(extra),"ordinary spawn etype4 has no start tag");
 for(int k=0;k<=20;k++){double y=NativeEnemyRigPolicy.AnchorY(100,200,80,100,k/20.0);Check(y>=100&&y<=200,"anchor remains inside projected bounds "+k);}
 Check(Math.Abs(NativeEnemyRigPolicy.AnchorY(100,200,80,100,.55)-135)<.0001,"foot plus chest projection");

 var expectedTypes=new[]{1,7,16,47,4};var expectedModels=new[]{"SpineApostle","SageApostle","TrapperApostle","ShadowTwin","CarapaceApostleV2"};var expectedHeights=new[]{1.35,1.27,1.27,1.42,1.49};var expectedChests=new[]{.618,.639,.570,.641,.625};
 for(int i=0;i<expectedTypes.Length;i++){EnemyRigDefinition found=null;int matches=0;foreach(var d in catalog.models)if(d.Matches(new EnemyState{Etype=expectedTypes[i]})){found=d;matches++;}Check(matches==1,"unique ordinary model key "+expectedTypes[i]);if(found==null)continue;Check(found.modelResource=="Enemies3D/"+expectedModels[i],"approved model resource "+expectedTypes[i]);Check(Math.Abs(found.height-expectedHeights[i])<.00001&&Math.Abs(found.chestRatio-expectedChests[i])<.00001,"producer impact metrics "+expectedTypes[i]);Check(found.baseRadius==EnemyTables.R[expectedTypes[i]],"Core base radius "+expectedTypes[i]);Check(found.move=="Walk","Core sampled walking slot "+expectedTypes[i]);Check(string.IsNullOrEmpty(found.idle)&&string.IsNullOrEmpty(found.tell)&&string.IsNullOrEmpty(found.active)&&string.IsNullOrEmpty(found.recover)&&string.IsNullOrEmpty(found.hit)&&string.IsNullOrEmpty(found.stagger)&&string.IsNullOrEmpty(found.death),"unprovided clips stay explicit "+expectedTypes[i]);}
 int eyeKeys=0;foreach(var d in catalog.models)if(d.Matches(new EnemyState{Etype=4,IsStartEyeMass=true})){eyeKeys++;Check(d.modelResource=="Enemies3D/EyeMass"&&string.IsNullOrEmpty(d.move),"start eye resource and missing walking unchanged");}Check(eyeKeys==1,"start eye key unique beside carapace");
 using(var provenance=JsonDocument.Parse(File.ReadAllText(Path.Combine(Path.GetDirectoryName(args[0]),"../Enemies3D/pilot-provenance.json")))){Check(provenance.RootElement.GetArrayLength()==6,"all six conversion sources recorded");foreach(var row in provenance.RootElement.EnumerateArray()){string model=row.GetProperty("model").GetString();Check(row.GetProperty("triangles").GetInt32()>8000,"body mesh excludes armature preview "+model);if(model!="EyeMass"){Check(row.GetProperty("bones").GetInt32()==24,"generic 24-bone rig "+model);Check(row.GetProperty("actions").GetArrayLength()==1&&row.GetProperty("actions")[0].GetString()=="Walk","provided walk exported "+model);}if(model=="CarapaceApostleV2")Check(row.GetProperty("source").GetString().Contains("carapace2_rig_"),"carapace v1 never adopted");if(model=="SpineApostle")Check(row.GetProperty("source").GetString().Contains("spine_walk_eyefix"),"spine eye correction adopted");}}
 Console.WriteLine(checks+" checks / "+fail+" failures");Environment.ExitCode=fail==0?0:1;
 }
}
